import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.Crpw6aS5.js";const i="/assets/01-banner.BilnyToz.png",g=JSON.parse('{"title":"Gauntlet Loop (DevinNorgarb/gauntlet-loop)","description":"Imported notes on the Gauntlet Loop agent skill — builder/critic pairs, blind comparison against a real quality bar, loop until it wins.","frontmatter":{"title":"Gauntlet Loop (DevinNorgarb/gauntlet-loop)","description":"Imported notes on the Gauntlet Loop agent skill — builder/critic pairs, blind comparison against a real quality bar, loop until it wins."},"headers":[],"relativePath":"misc/artificial-intelligence/github-gauntlet-loop.md","filePath":"misc/artificial-intelligence/github-gauntlet-loop.md"}'),o={name:"misc/artificial-intelligence/github-gauntlet-loop.md"};function r(l,e,p,h,c,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="gauntlet-loop" tabindex="-1">Gauntlet Loop <a class="header-anchor" href="#gauntlet-loop" aria-label="Permalink to &quot;Gauntlet Loop&quot;">​</a></h1><p><img src="'+i+`" alt="Gauntlet Loop banner"></p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://github.com/DevinNorgarb/gauntlet-loop" target="_blank" rel="noreferrer">https://github.com/DevinNorgarb/gauntlet-loop</a></li><li>Imported: 2026-08-20</li><li>Images: 1 (banner PNG saved under <code>./assets/github-gauntlet-loop/</code>)</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><a href="https://github.com/DevinNorgarb/gauntlet-loop" target="_blank" rel="noreferrer">Gauntlet Loop</a> is a skill that turns any goal into one short, paste-ready prompt. That prompt makes your agent pick a real quality bar, split the work into small pieces, run a builder and a separate harsh critic on each one, compare blind against the bar, and keep looping until it wins.</p><p>Most agent output stops at &quot;good enough&quot; because nothing is holding it to a standard. This gives it a standard it cannot argue with.</p><blockquote><p>The gauntlet loop is <a href="https://github.com/mshumer" target="_blank" rel="noreferrer">Matt Shumer&#39;s</a> idea. He wrote the original prompt and named the technique while building <a href="https://github.com/mshumer/Claude-of-Duty" target="_blank" rel="noreferrer">Claude of Duty</a>. This repo packages that pattern as a reusable skill.</p></blockquote><h3 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/DevinNorgarb/gauntlet-loop</span></span></code></pre></div><p>Copy the skill folder into your project:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gauntlet-loop/.claude/skills/gauntlet-loop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project/.claude/skills/</span></span></code></pre></div><p>Then in your agent:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gauntlet-loop build me a pricing page for my SaaS</span></span></code></pre></div><p>It offers you 2 or 3 quality bars to aim at, you pick one, and it hands back a single prompt you paste into a fresh session.</p><h3 id="what-s-included" tabindex="-1">What&#39;s included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s included&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/skills/gauntlet-loop/</span></span>
<span class="line"><span>└── SKILL.md      # the whole skill, one file</span></span>
<span class="line"><span>README.md</span></span>
<span class="line"><span>LICENSE           # CC BY 4.0</span></span></code></pre></div><h3 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h3><ol><li><strong>You give a goal.</strong> Anything — a site, an essay, a CLI tool, a research brief.</li><li><strong>It offers 2 or 3 bars.</strong> Each one is a specific, real thing your agent can actually fetch and compare against. Not &quot;award-winning design&quot;, but a named page, a named post, a named repo.</li><li><strong>You pick one.</strong> It writes one short prompt, around 150 words, and stops.</li><li><strong>You paste it into a fresh session.</strong> That agent splits the work, runs builder and critic pairs, and loops.</li></ol><p>The critic is the part that matters. It is a separate agent with fresh context, it opens the actual output, it puts your work next to the bar with the labels stripped, and it says which one is better. Not a score out of 10, which drifts upward every round — a pick.</p><p>The loop exits when your work wins the blind comparison, or when you stop the run. Never after a fixed number of rounds.</p><h3 id="why-a-bar-and-not-a-rubric" tabindex="-1">Why a bar and not a rubric <a class="header-anchor" href="#why-a-bar-and-not-a-rubric" aria-label="Permalink to &quot;Why a bar and not a rubric&quot;">​</a></h3><p>A rubric asks the agent to grade itself against words it wrote. A bar makes it compare against something that already exists and is undeniably good.</p><p>The skill will not accept a vague bar. It checks three things before it writes anything:</p><ul><li><strong>Named.</strong> A specific thing, not a category.</li><li><strong>Fetchable.</strong> The critic can screenshot it, read it, run it, or open it. If the agent cannot get the reference, it hallucinates the comparison and approves everything.</li><li><strong>Comparable.</strong> Both can sit side by side and a judge can pick one.</li></ul><table tabindex="0"><thead><tr><th>Goal</th><th>Bar that works</th></tr></thead><tbody><tr><td>Website, app, UI</td><td>The live site of a specific best-in-class product, screenshotted at the same viewport</td></tr><tr><td>Game, 3D, visual</td><td>Real footage or screenshots from a named shipped title</td></tr><tr><td>Writing</td><td>A specific published piece by a named author or publication, same length and format</td></tr><tr><td>Code, tooling</td><td>A named repo&#39;s implementation, plus its benchmark or test suite as the measurable half</td></tr><tr><td>Research, analysis</td><td>A named analyst report or a paper&#39;s methods section, judged on rigour and coverage</td></tr><tr><td>Deck, doc, deliverable</td><td>A real artifact from a firm known for it, same page count</td></tr></tbody></table><h3 id="prompt-template" tabindex="-1">Prompt template <a class="header-anchor" href="#prompt-template" aria-label="Permalink to &quot;Prompt template&quot;">​</a></h3><p>Adapt the wording every time. Fill the brackets, keep it short, keep the last line.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build [GOAL].</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The bar is [BAR]. Get the real thing first and compare against it directly, not against a description of it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Break this into the smallest pieces that can be improved and judged on their own. For each piece, fan out a builder and a separate critic with fresh context. The critic inspects the actual output, puts it next to the bar blind with the labels stripped, says which one is better, and names the single biggest remaining gap. Then it goes back to the builder.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The critic should be a harsh critic. Praise is not useful. If ours does not win, it keeps going.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/loop on each piece until the critic picks ours blind. Do not stop before that.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Keep a live progress page updating as the work evolves so I can watch it.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fan out subagents and ultracode.</span></span></code></pre></div><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gauntlet-loop a landing page for my running brand, dark and green, has to feel alive</span></span></code></pre></div><p>Bar becomes a specific brand&#39;s live campaign page, screenshotted at desktop and mobile.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gauntlet-loop a 2000 word explainer on vector databases for non-engineers</span></span></code></pre></div><p>Bar becomes a named writer&#39;s actual published posts, judged on which one a non-engineer understands faster.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gauntlet-loop a CLI that formats JSON logs</span></span></code></pre></div><p>Bar becomes a named tool&#39;s implementation plus its benchmark, so taste and a number both have to win.</p><h3 id="works-with-any-agent" tabindex="-1">Works with any agent <a class="header-anchor" href="#works-with-any-agent" aria-label="Permalink to &quot;Works with any agent&quot;">​</a></h3><p><code>/loop</code> and <code>ultracode</code> are Claude Code features. <code>/loop</code> reruns a prompt until you stop it, and <code>ultracode</code> opts a turn into multi-agent orchestration.</p><p>For any other agent, the skill swaps those two lines for plain instructions: keep looping until the critic picks ours, and run the builders and critics as parallel subagents. The structure is identical.</p><h3 id="what-breaks-it" tabindex="-1">What breaks it <a class="header-anchor" href="#what-breaks-it" aria-label="Permalink to &quot;What breaks it&quot;">​</a></h3><ul><li><strong>A vague bar.</strong> The critic invents a comparison and approves everything. By far the most common failure.</li><li><strong>The builder judging its own work.</strong> The critic needs fresh context and no knowledge of how hard the builder tried.</li><li><strong>A soft critic.</strong> Give it a binary job, not a score.</li><li><strong>A fixed round count.</strong> The exit is winning, or you calling it.</li><li><strong>Over-specifying.</strong> Every extra instruction is one fewer decision the agent makes with its own judgment.</li></ul><h3 id="credit-and-license" tabindex="-1">Credit and license <a class="header-anchor" href="#credit-and-license" aria-label="Permalink to &quot;Credit and license&quot;">​</a></h3><p>The gauntlet loop technique is <strong><a href="https://github.com/mshumer" target="_blank" rel="noreferrer">Matt Shumer&#39;s</a></strong>. He built <a href="https://github.com/mshumer/Claude-of-Duty" target="_blank" rel="noreferrer">Claude of Duty</a>, wrote the <a href="https://github.com/mshumer/Claude-of-Duty/blob/main/prompt.md" target="_blank" rel="noreferrer">original prompt</a>, and named the loop. Every idea underneath this skill — the harsh critic, the blind comparison, the refusal to stop until the work wins — comes from that prompt.</p><p>This repo is not the technique. It is a skill that writes a gauntlet loop prompt for you, for any goal, so you do not have to hand-write one each time.</p><p>Related reading: <a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic on building effective agents</a>, which covers the evaluator pattern the loop is built on.</p><p>Licensed <strong>CC BY 4.0</strong>. Skill by Jay E at <a href="https://robonuggets.com" target="_blank" rel="noreferrer">RoboNuggets</a>. Technique by Matt Shumer.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>A gauntlet loop holds agent output to a <strong>real, fetchable reference</strong> — not a self-written rubric.</li><li>Each piece gets a <strong>builder + separate harsh critic</strong>; the critic picks blind (A or B), not a drifting score.</li><li>The loop <strong>only exits when your work wins</strong> the comparison or you stop the run — never after a fixed round count.</li><li>The skill&#39;s job is to <strong>write the ~150-word paste-ready prompt</strong>; you run it in a fresh session for best results.</li></ul>`,48)])])}const b=t(o,[["render",r]]);export{g as __pageData,b as default};
